#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <deque>
#include <vector>
namespace PlagC
{
namespace
{
using Clock=std::chrono::steady_clock;constexpr unsigned StageCount=static_cast<unsigned>(LatencyStage::Count);
struct Transition{std::uint64_t id=0,callbackFrame=0;Clock::time_point callback{};bool release=false,movement=false;KeyCode key=KeyCode::Unknown;MouseCode button=MouseCode::Unknown;std::array<bool,StageCount> marked{};};
struct Samples{std::vector<double> ms,frames;};
struct State{Clock::time_point pollStart{},windowStart=Clock::now();std::uint64_t frame=0,nextId=1,transitions=0,presses=0,releases=0,movementReleases=0,mouseMoves=0;std::deque<Transition> pending;std::vector<double> pollSamples;std::array<Samples,StageCount> stage;unsigned physicsSteps=0;double physicsAlpha=0,physicsDroppedMs=0;bool gpuSupported=false,gpuValid=false;double gpuMs=0;std::uint32_t gpuQueryLatencyFrames=0,gpuOutstandingFrames=0;}state;
double Ms(Clock::duration d){return std::chrono::duration<double,std::milli>(d).count();}double Average(const std::vector<double>&v){double s=0;for(double x:v)s+=x;return v.empty()?0:s/double(v.size());}double Maximum(const std::vector<double>&v){return v.empty()?0:*std::max_element(v.begin(),v.end());}double Percentile(std::vector<double>v,double q){if(v.empty())return 0;std::sort(v.begin(),v.end());auto i=static_cast<std::size_t>(std::ceil(q*double(v.size()))-1);return v[std::min(i,v.size()-1)];}bool MovementKey(KeyCode k){return k==KeyCode::W||k==KeyCode::A||k==KeyCode::S||k==KeyCode::D||k==KeyCode::LeftShift||k==KeyCode::LeftAlt||k==KeyCode::Space;}
void Mark(LatencyStage stage){const auto now=Clock::now();const auto index=static_cast<unsigned>(stage);for(auto&t:state.pending)if(!t.marked[index]){t.marked[index]=true;state.stage[index].ms.push_back(Ms(now-t.callback));state.stage[index].frames.push_back(double(state.frame-t.callbackFrame));}if(stage==LatencyStage::RenderSubmit)while(!state.pending.empty()&&state.frame-state.pending.front().callbackFrame>8)state.pending.pop_front();}
}
void LatencyProfiler::BeginFrame(){++state.frame;}std::uint64_t LatencyProfiler::Frame(){return state.frame;}void LatencyProfiler::BeginPoll(){state.pollStart=Clock::now();}void LatencyProfiler::EndPoll(){if(state.pollStart!=Clock::time_point{})state.pollSamples.push_back(Ms(Clock::now()-state.pollStart));}
void LatencyProfiler::OnCallback(const Event&e){if(e.type==EventType::MouseMoved){++state.mouseMoves;return;}const bool press=e.type==EventType::KeyPressed||e.type==EventType::MousePressed;const bool release=e.type==EventType::KeyReleased||e.type==EventType::MouseReleased;if(!press&&!release)return;++state.transitions;if(release)++state.releases;else ++state.presses;const bool movement=e.key!=KeyCode::Unknown&&MovementKey(e.key);if(release&&movement)++state.movementReleases;Transition t;t.id=state.nextId++;t.callbackFrame=state.frame;t.callback=Clock::now();t.release=release;t.movement=movement;t.key=e.key;t.button=e.button;state.pending.push_back(t);while(state.pending.size()>128)state.pending.pop_front();}
void LatencyProfiler::OnInputStateApplied(const Event&){}void LatencyProfiler::OnGameRead(){Mark(LatencyStage::GameRead);}void LatencyProfiler::OnMovementIntent(Vec3){Mark(LatencyStage::MovementIntent);}void LatencyProfiler::OnPhysicsInput(Vec3){Mark(LatencyStage::PhysicsInput);}void LatencyProfiler::OnPhysicsPlan(unsigned steps,double alpha,double droppedSeconds){state.physicsSteps=steps;state.physicsAlpha=alpha;state.physicsDroppedMs=droppedSeconds*1000.0;}void LatencyProfiler::OnPhysicsStep(){Mark(LatencyStage::PhysicsStep);}void LatencyProfiler::OnPhysicsOutput(){Mark(LatencyStage::PhysicsOutput);}void LatencyProfiler::OnWorldTransform(){Mark(LatencyStage::WorldTransform);}void LatencyProfiler::OnCamera(){Mark(LatencyStage::Camera);}void LatencyProfiler::OnAnimation(){Mark(LatencyStage::Animation);}void LatencyProfiler::OnSceneSync(){Mark(LatencyStage::SceneSync);}void LatencyProfiler::OnRenderSubmit(){Mark(LatencyStage::RenderSubmit);}
void LatencyProfiler::OnGpuTiming(bool supported,bool valid,double totalMs,std::uint32_t latency,std::uint32_t outstanding){state.gpuSupported=supported;state.gpuValid=valid;state.gpuOutstandingFrames=outstanding;if(valid){state.gpuMs=totalMs;state.gpuQueryLatencyFrames=latency;}}
LatencySnapshot LatencyProfiler::ConsumeOneSecond(){LatencySnapshot out{};const auto now=Clock::now();if(Ms(now-state.windowStart)<1000)return out;out.transitions=state.transitions;out.presses=state.presses;out.releases=state.releases;out.movementReleases=state.movementReleases;out.mouseMoves=state.mouseMoves;out.pollMs=Average(state.pollSamples);out.pollP99Ms=Percentile(state.pollSamples,.99);out.pollMaxMs=Maximum(state.pollSamples);for(const auto&t:state.pending)out.oldestPendingMs=std::max(out.oldestPendingMs,Ms(now-t.callback));for(unsigned i=0;i<StageCount;++i){auto&s=out.stages[i];s.averageMs=Average(state.stage[i].ms);s.p99Ms=Percentile(state.stage[i].ms,.99);s.maxMs=Maximum(state.stage[i].ms);s.averageFrames=Average(state.stage[i].frames);s.maxFrames=Maximum(state.stage[i].frames);s.samples=state.stage[i].ms.size();state.stage[i].ms.clear();state.stage[i].frames.clear();}out.physicsSteps=state.physicsSteps;out.physicsAlpha=state.physicsAlpha;out.physicsDroppedMs=state.physicsDroppedMs;out.gpuSupported=state.gpuSupported;out.gpuValid=state.gpuValid;out.gpuMs=state.gpuMs;out.gpuQueryLatencyFrames=state.gpuQueryLatencyFrames;out.gpuOutstandingFrames=state.gpuOutstandingFrames;out.frame=state.frame;state.pollSamples.clear();state.transitions=state.presses=state.releases=state.movementReleases=state.mouseMoves=0;state.windowStart=now;return out;}
} // namespace PlagC
