{void LatencyProfiler::BeginFrame(){}std::uint64_t LatencyProfiler::Frame(){return 0;}void LatencyProfiler::BeginPoll(){}void LatencyProfiler::EndPoll(){}void LatencyProfiler::OnCallback(const Event&){}void LatencyProfiler::OnInputStateApplied(const Event&){}void LatencyProfiler::OnGameRead(){}void LatencyProfiler::OnMovementIntent(Vec3){}void LatencyProfiler::OnPhysicsInput(Vec3){}void LatencyProfiler::OnPhysicsPlan(unsigned,double,double){}void LatencyProfiler::OnPhysicsStep(){}void LatencyProfiler::OnPhysicsOutput(){}void LatencyProfiler::OnWorldTransform(){}void LatencyProfiler::OnCamera(){}void LatencyProfiler::OnAnimation(){}void LatencyProfiler::OnSceneSync(){}void LatencyProfiler::OnRenderSubmit(){}void LatencyProfiler::OnGpuTiming(bool,bool,double,std::uint32_t,std::uint32_t){}LatencySnapshot LatencyProfiler::ConsumeOneSecond(){return {};}}
